head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// 호출메뉴ID를 식별하기 위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common_etn.js");
// 상장관련공통함수
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
scwin.vScrenID = "ULDSTF08054.xml";
scwin.fr_SecuGrpId = SECUGRP_ID_EN;
scwin.fr_MktId = $c.lce.fn_getMktId(); // 시장구분코드(유가, 코스닥) 전체), 기준은 로그인 사용자의 부서 소속을 기준으로 한다.

scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vIsurCd = "";
scwin.vLIST_STAT_CD = "Y";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
}; // jackal_11.05.12 상장종목 여부 체크 추가

scwin.fn_search = function() {
    var url = "/etn/EtnMktAct.do?method=searchDelist" + "&DIV_IDX=" + DIV_IDX_ETN_DELLIST_LIST_CORP_INFO + "&TRS_IDX=" + TRS_IDX_SELECT + "&ISUR_CD=99999";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts.DataID = encodeURI(url);
    dts.reset();
    $c.cm.ShowWin(grd);
};
scwin.fn_search2 = function() {
    var url = "/etn/EtnMktAct.do?method=searchDelist" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    if (rdo_ISUR_CD_1.getValue() == "1") {
        if (txb_ISU_CD.getValue() == "") {
            url += "&DIV_IDX=" + DIV_IDX_ETN_DELLIST_LIST_ALL_INFO + "&TRS_IDX=" + TRS_IDX_SELECT + "&GUBUN_CD=ETN";
        } else {
            url += "&DIV_IDX=" + DIV_IDX_ETN_DELLIST_LIST_ISU_INFO + "&TRS_IDX=" + TRS_IDX_SELECT + "&ISU_CD=" + txb_ISU_CD.getValue();
        }
    } else if (rdo_ISUR_CD_2.getValue() == "1") {
        if (cmb_ISUR_CD.getSelectedIndex() == 0) {
            url += "&DIV_IDX=" + DIV_IDX_ETN_DELLIST_LIST_ALL_INFO + "&TRS_IDX=" + TRS_IDX_SELECT + "&GUBUN_CD=ETN";
        } else {
            url += "&DIV_IDX=" + DIV_IDX_ETN_DELLIST_LIST_CORP_INFO + "&TRS_IDX=" + TRS_IDX_SELECT + "&ISUR_CD=" + cmb_ISUR_CD.BindColVal;
        }
    }
    dts2.DataID = encodeURI(url);
    dts2.reset();
    $c.cm.ShowWin(grd2);
};
scwin.fn_GetParUpdate = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = scwin.fr_SecuGrpId; // 증권그룹구분	
    arrPar[1] = scwin.fr_MktId; // 시장구분
    arrPar[2] = dts.getCellData(dts.getRowPosition(), "bz_procs_no"); // 업무처리번호
    arrPar[3] = dts.getCellData(dts.getRowPosition(), "WRT_DD"); // 최종거래일

    return arrPar.length;
};
scwin.fn_GetParNew = function(arrPar) {
    // 신규생성시 지정하는 평션
    arrPar[0] = scwin.fr_SecuGrpId; // 증권그룹구분	
    arrPar[1] = scwin.fr_MktId; // 시장구분
    arrPar[2] = ""; // 신규작성시 업무처리번호는 없다.
    arrPar[3] = $c.ut.cGetToday("yyyymmdd");
};
scwin.fn_GetParUpdate2 = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    if (rdo_ISUR_CD_1.getValue() == "1") {
        arrPar[0] = scwin.vIsurCd; // 발행기관코드값
        arrPar[1] = txb_ISU_NM.getValue(); // 종목명
        arrPar[5] = txb_ISU_CD.getValue(); // 종목코드값
        arrPar[6] = "1"; // 선택 구분(1:종목, 2:발행회사, 3:전체)

    } else if (rdo_ISUR_CD_2.getValue() == "1") {
        if (cmb_ISUR_CD.getSelectedIndex() == 0) {
            arrPar[0] = scwin.vIsurCd; // 발행기관코드값
            arrPar[1] = ""; // 발행기관명
            arrPar[5] = ""; // 종목코드값
            arrPar[6] = "3"; // 선택 구분(1:종목, 2:발행회사, 3:전체)

        } else {
            arrPar[0] = cmb_ISUR_CD.BindColVal; // 발행기관코드값
            arrPar[1] = cmb_ISUR_CD.getText(); // 발행기관명
            arrPar[5] = rdo_ISUR_CD_2.getValue(); // 발행사/기초자산 구분값
            arrPar[6] = "2"; // 선택 구분(1:종목, 2:발행회사, 3:전체)

        }
    }
    arrPar[2] = scwin.fr_SecuGrpId; // 증권그룹구분	
    arrPar[3] = scwin.fr_MktId; // 시장구분
    arrPar[4] = dts2.getCellData(dts2.getRowPosition(), "bz_procs_no"); // 업무처리번호
    //arrPar[3] = dts2.NameString(dts2.RowPosition, "ELW_LSTTRD_DD"); // 최종거래일

    return arrPar.length;
};
scwin.fn_GetParNew2 = function(arrPar) {
    if (rdo_ISUR_CD_1.getValue() == "1") {
        arrPar[0] = scwin.vIsurCd; // 발행기관코드값
        arrPar[1] = txb_ISU_NM.getValue(); // 종목명
        arrPar[5] = txb_ISU_CD.getValue(); // 종목코드값
        arrPar[6] = "1"; // 선택 구분(1:종목, 2:발행회사, 3:전체)

    } else if (rdo_ISUR_CD_2.getValue() == "1") {
        if (cmb_ISUR_CD.getSelectedIndex() == 0) {
            arrPar[0] = ""; // 발행기관코드값
            arrPar[1] = ""; // 발행기관명
            arrPar[5] = ""; // 종목코드값
            arrPar[6] = "3"; // 선택 구분(1:종목, 2:발행회사, 3:전체)

        } else {
            arrPar[0] = cmb_ISUR_CD.BindColVal; // 발행기관코드값
            arrPar[1] = cmb_ISUR_CD.getText(); // 발행기관명
            arrPar[5] = rdo_ISUR_CD_2.getValue(); // 발행사/기초자산 구분값
            arrPar[6] = "2"; // 선택 구분(1:종목, 2:발행회사, 3:전체)

        }
    }
    arrPar[2] = scwin.fr_SecuGrpId; // 증권그룹구분	
    arrPar[3] = scwin.fr_MktId; // 시장구분
    arrPar[4] = ""; // 신규작성시 업무처리번호는 없다.

};
scwin.fn_new_create_frame = async function() {
    await $c.frame.CreateDialogFrame("DLG_DELLIST", "../etn/ULDSTF08055_new.gfm", $c.lce.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + " 만기 1개월 전 상장폐지 예고", 200, 100, 780, 570, "window");
    scwin.fn_search(); // 다이얼로그 창이 닫히면 조회를 보낸다.

};
scwin.fn_newpre_create_frame = async function() {
    await $c.frame.CreateDialogFrame("DLG_DELLIST", "../etn/ULDSTF08055.gfm", $c.lce.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + " 만기 1개월 전 상장폐지 예고", 200, 100, 730, 570, "window");
    scwin.fn_search(); // 다이얼로그 창이 닫히면 조회를 보낸다.

};
scwin.fn_new_create_frame2 = async function() {
    await $c.frame.CreateDialogFrame("DLG_DELLIST", "../etn/ULDSTF08056_new.gfm", $c.lce.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + " 기타 사유에 의한 상장폐지 예고", 200, 100, 730, 530, "window");
    scwin.fn_search2(); // 다이얼로그 창이 닫히면 조회를 보낸다.

};
scwin.fn_newpre_create_frame2 = async function() {
    await $c.frame.CreateDialogFrame("DLG_DELLIST", "../etn/ULDSTF08056.gfm", $c.lce.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + " 기타 사유에 의한 상장폐지 예고", 200, 100, 730, 530, "window");
    scwin.fn_search2(); // 다이얼로그 창이 닫히면 조회를 보낸다.

};


//etn발행사
scwin.fn_get_isurcode = function() {
    //etn발행사
    dts_EtnInst.DataID = "/etn/EtnCodeAct.do?method=listIsurCd&For=R";
    dts_EtnInst.Reset();
};


// dialog 호출용 함수
// 예비심사청구제출기관 호출관련
scwin.fn_GetParIsur = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = ""; // 코드값을 포함할 컨트롤
    arrPar[1] = $c.stf.getObjectValue(txb_ISU_NM); // 명칭값을 포함할 컨트롤
    arrPar[2] = scwin.fr_SecuGrpId; // 명칭값을 포함할 컨트롤

    return arrPar.length;
};
scwin.fn_SetParIsur = function(arrPar) {
    var dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn == "Y") {
        scwin.fn_changeRadioBtn(1);
        txb_ISU_CD.setValue(arrPar[0].ISU_CD);
        //txb_ISU_NM.value = arrPar[0].ISU_KOR_NM;
        txb_ISU_NM.setValue(arrPar[0].ISU_KOR_ABBRV);
        scwin.vIsurCd = arrPar[0].ISUR_CD;
        scwin.fn_search2();
    }

    //jackal_11.05.12
    // 삭제 종목인 경우 모든 버튼 discable
    scwin.vLIST_STAT_CD = arrPar[0].LIST_STAT_CD;
    if (scwin.vLIST_STAT_CD == "D") {
        img_Regist2.setDisabled(true);
        img_Regist2.src = "../img/btn_new_d.gif";
    } else {
        img_Regist2.setDisabled(false);
        img_Regist2.src = "../img/btn_new.gif";
    }
};
scwin.fn_changeRadioBtn = function(idx) {
    if (idx == "1") {
        cmb_ISUR_CD.setSelectedIndex(0);
        rdo_ISUR_CD_1.setValue("1");
        rdo_ISUR_CD_2.setValue("2");
    } else if (idx == "2") {
        txb_ISU_CD.setValue("");
        txb_ISU_NM.setValue("");
        rdo_ISUR_CD_1.setValue("2");
        rdo_ISUR_CD_2.setValue("1");
    }
};
scwin.img_Search_onclick = function() {
    scwin.fn_search();
};
scwin.img_Search2_onclick = function() {
    //if(rdo_ISUR_CD_1.CodeValue == "1"){
    //	if (txb_ISU_CD.value == "") {
    //		alert(getMessageParam("MSG-0015", ""));
    //		return true;
    //	} 
    //}
    scwin.fn_search2();
};
scwin.img_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    if (dts.getTotalRow() > 0) {
        $c.data.downloadGridViewExcel(grd, $c.lce.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + " 만기 1개월 전 상장폐지예고", "", "8");
    } else {
        $c.win.alert(NO_EXCEL_DATA);
    }
};
scwin.img_Excel2_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    if (dts2.getTotalRow() > 0) {
        $c.data.downloadGridViewExcel(grd2, $c.lce.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + " 기타 사유에 의한 상장폐지예고", "", "8");
    } else {
        $c.win.alert(NO_EXCEL_DATA);
    }
};
scwin.img_Etnlist_OnSelChanged = function(nIndex) {
    if (nIndex == 1) {
        scwin.fn_search();
    }
    if (nIndex == 2) // ko_jackal_10.06.15

    {
        rdo_ISUR_CD_1.setValue("1");
        rdo_ISUR_CD_2.setValue("2");
        txb_ISU_CD.setValue("");
        txb_ISU_NM.setValue("");
        cmb_ISUR_CD.setSelectedIndex(0);

        //fn_search2();

    }
};
scwin.dts_OnLoadError = function() {
    $c.stf.alert_error(dts);
};
scwin.dts_OnLoadCompleted = function(rowcount) {
    txb_TotCnt.setValue("총건수 : " + rowcount);
    //dts.RowPosition = rowcount;
    $c.cm.CloseWin(rowcount, grd);
};
scwin.dts2_OnLoadError = function() {
    $c.stf.alert_error(dts2);
};
scwin.dts2_OnLoadCompleted = function(rowcount) {
    txb_TotCnt2.setValue("총건수 : " + rowcount);
    //dts2.RowPosition = rowcount;
    $c.cm.CloseWin(rowcount, grd2);
};
scwin.btn_iSU_CD_onclick = function() {
    scwin.fn_GetPar = fn_GetParIsur;
    scwin.fn_SetPar = fn_SetParIsur;
    //fn_PopFindIsu(fr_SecuGrpId);
    //fn_PopFindIsuAll(fr_SecuGrpId);		// jackal_11.05.12
    $c.lce.fn_PopFindEtnIsuAll(scwin.fr_SecuGrpId);
};
scwin.img_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.img_Close2_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.img_Regist_onclick = function() {
    scwin.fn_GetPar = fn_GetParNew;
    scwin.fn_SetPar = undefined;
    scwin.fn_new_create_frame();
};
scwin.img_Regist2_onclick = function() {
    if (rdo_ISUR_CD_1.getValue() == "1") {
        if (txb_ISU_CD.getValue() == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-0015", ""));
            return true;
        }
    }
    scwin.fn_GetPar = fn_GetParNew2;
    scwin.fn_SetPar = undefined;
    if (rdo_ISUR_CD_2.getValue() == "1") {
        scwin.fn_new_create_frame2();
    } else {
        scwin.fn_newpre_create_frame2();
    }
};
scwin.grd_OnDblClick = function(row, colid) {
    if (row == 0) return;
    scwin.vIsurCd = dts.getCellData(row, "ISUR_CD");
    scwin.fn_GetPar = fn_GetParUpdate; // 수정시 인수를 넘기는 function을 fn_GetPar란 변수에 할당, (팝업화면에서 참조하는 변수명이 fn_GetPar임)
    scwin.fn_SetPar = undefined;
    scwin.fn_newpre_create_frame();
};
scwin.grd2_OnDblClick = function(row, colid) {
    if (row == 0) return;
    scwin.vIsurCd = dts2.getCellData(row, "ISUR_CD");
    scwin.fn_GetPar = fn_GetParUpdate2; // 수정시 인수를 넘기는 function을 fn_GetPar란 변수에 할당, (팝업화면에서 참조하는 변수명이 fn_GetPar임)
    scwin.fn_SetPar = undefined;
    scwin.fn_newpre_create_frame2();
};
scwin.rdo_ISUR_CD_1_OnClick = function() {
    //rdo_ISUR_CD_2.CodeValue ="2";
    scwin.fn_changeRadioBtn(1);
    scwin.fn_search2();
};
scwin.rdo_ISUR_CD_2_OnClick = function() {
    //rdo_ISUR_CD_1.CodeValue ="2";
    scwin.fn_changeRadioBtn(2);
    scwin.fn_search2();
};
scwin.cmb_ISUR_CD_OnSelChange = function() {
    scwin.fn_changeRadioBtn(2);
    scwin.fn_search2();
};
scwin.gform_onload = function() {
    $c.libRoundPanel.PanelToGroupBox(pan_Cnd);
    scwin.fn_get_isurcode();
    img_Etnlist.setSelectedTabIndex(1);
    scwin.fn_search();
};
